WITH with_last AS (SELECT s.*, top1.level, top1.hire_date FROM departments s LEFT JOIN LATERAL (SELECT c.level, c.hire_date FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT DATE_TRUNC('YEAR', hire_date) AS year_start, CASE WHEN budget >= 4382000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, DATE_TRUNC('WEEK', hire_date) AS week_start, APPROX_PERCENTILE(budget, 0.5) AS budget_p50, SUM(CASE WHEN location = 'Singapore' THEN budget ELSE 0 END) AS singapore_budget, COUNT(*) FILTER (WHERE dept_name = 'Engineering') AS engineering_rows, MAX(budget) AS max_budget FROM with_last GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', hire_date), CASE WHEN budget >= 4382000 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', hire_date)), (DATE_TRUNC('YEAR', hire_date), CASE WHEN budget >= 4382000 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('YEAR', hire_date))) ORDER BY budget_p50 ASC NULLS FIRST
